const item = $input.first().json;

const sourceAccount = item.sourceAccount;
const subject = item.subject || '(no subject)';

let senderEmail = item.from || '';
let senderName = '';
const match = String(senderEmail).match(/^(.*?)\s*<([^>]+)>/);
if (match) {
  senderName = match[1].trim();
  senderEmail = match[2];
}

const messageId = item.messageId || item.uid || `${sourceAccount}-${Date.now()}`;
const receivedAt = new Date(item.date || Date.now()).toISOString();
const body = (item.textPlain || item.text || item.html || '').toString().slice(0, 12000);

const attachments = item.attachments || [];
const attachmentNames = attachments.map((a) => a.filename || a.name).filter(Boolean);

return [
  {
    json: {
      sourceAccount,
      externalMessageId: messageId,
      senderEmail: senderEmail || 'unknown@unknown.com',
      senderName,
      subject,
      receivedAt,
      body,
      hasAttachments: attachmentNames.length > 0,
      attachmentNames,
    },
  },
];

const SYSTEM_PROMPT =
  'You are an email intelligence assistant for ExpressWay Logistics. Classify into ONE category: shipment, quotation, alert, or general. Return JSON: { category, confidence, summary, urgency, extractedData }. Shipment fields: awb, trackingNo, pickup, destination, status, eta. Quotation: quoteNo, origin, destination, carrier, price, validity. Alert: alertType, urgency, requiredAction, deadline. General: sender, subject, date, summary.';

const email = $input.first().json;

const userContent = [
  `From: ${email.senderName || ''} <${email.senderEmail}>`,
  `Subject: ${email.subject}`,
  `Date: ${email.receivedAt}`,
  '',
  email.body || '',
].join('\n');

const messages = [
  { role: 'system', content: SYSTEM_PROMPT },
  { role: 'user', content: userContent },
];

const groqKey = $env.GROQ_API_KEY;
const geminiKey = $env.GEMINI_API_KEY;
const openaiKey = $env.OPENAI_API_KEY;

let response;
let provider = 'unknown';

if (groqKey) {
  provider = 'groq';
  response = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.groq.com/openai/v1/chat/completions',
    headers: {
      Authorization: `Bearer ${groqKey}`,
      'Content-Type': 'application/json',
    },
    body: {
      model: 'llama-3.3-70b-versatile',
      temperature: 0.1,
      response_format: { type: 'json_object' },
      messages,
    },
    json: true,
  });
} else if (geminiKey) {
  provider = 'gemini';
  const geminiRes = await this.helpers.httpRequest({
    method: 'POST',
    url: `https://generativelanguage.googleapis.com/v1beta/models/gemini-2.0-flash:generateContent?key=${geminiKey}`,
    headers: { 'Content-Type': 'application/json' },
    body: {
      contents: [{ parts: [{ text: `${SYSTEM_PROMPT}\n\n${userContent}` }] }],
      generationConfig: {
        temperature: 0.1,
        responseMimeType: 'application/json',
      },
    },
    json: true,
  });
  response = {
    choices: [
      {
        message: {
          content: geminiRes.candidates?.[0]?.content?.parts?.[0]?.text || '',
        },
      },
    ],
  };
} else if (openaiKey) {
  provider = 'openai';
  response = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.openai.com/v1/chat/completions',
    headers: {
      Authorization: `Bearer ${openaiKey}`,
      'Content-Type': 'application/json',
    },
    body: {
      model: 'gpt-4o-mini',
      temperature: 0.1,
      response_format: { type: 'json_object' },
      messages,
    },
    json: true,
  });
} else {
  throw new Error(
    'No AI key found. Add GROQ_API_KEY (free — console.groq.com) or GEMINI_API_KEY (free — aistudio.google.com) to .env.local and restart n8n.',
  );
}

const content = response.choices?.[0]?.message?.content || '';
const cleaned = content.replace(/```json\n?/gi, '').replace(/```\n?/g, '').trim();

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch {
  parsed = {
    category: 'general',
    confidence: 0.4,
    summary: 'Parse failed',
    urgency: 'low',
    extractedData: {},
  };
}

parsed._aiProvider = provider;

return [{ json: parsed }];

const email = $('Prepare Email Context').first().json;
const ai = $input.first().json;

const payload = {
  sourceAccount: email.sourceAccount,
  externalMessageId: email.externalMessageId,
  senderEmail: email.senderEmail,
  subject: email.subject,
  receivedAt: email.receivedAt,
  category: ai.category,
  confidence: ai.confidence,
  summary: ai.summary,
  urgency: ai.urgency,
  hasAttachments: email.hasAttachments,
  attachmentNames: email.attachmentNames,
  extractedData: ai.extractedData || {},
};

if (email.senderName) payload.senderName = email.senderName;

return [{ json: payload }];
